class Solution {
public:
    bool hasSameDigits(string s) {
        vector<int> d;
        for (char ch : s) d.push_back(ch - '0');
        while (d.size() > 2) {
            vector<int> nd;
            for (int i = 0; i + 1 < (int)d.size(); i++) nd.push_back((d[i] + d[i + 1]) % 10);
            d.swap(nd);
        }
        return d[0] == d[1];
    }
};

