class Solution {
    public boolean hasSameDigits(String s) {
        int[] d = new int[s.length()];
        for (int i = 0; i < d.length; i++) d[i] = s.charAt(i) - '0';
        int len = d.length;
        while (len > 2) {
            for (int i = 0; i + 1 < len; i++) d[i] = (d[i] + d[i + 1]) % 10;
            len--;
        }
        return d[0] == d[1];
    }
}

