class Solution:
    def hasSameDigits(self, s: str) -> bool:
        import math
        n = len(s); m = n - 2
        d5 = []
        x = m
        while x:
            d5.append(x % 5); x //= 5
        C5 = [[math.comb(i, j) % 5 for j in range(i + 1)] + [0] * (4 - i) for i in range(5)]
        def c5(k):
            res, cur = 1, 1
            for p in d5:
                r = (k // cur) % 5; cur *= 5
                if r > p: return 0
                res = res * C5[p][r] % 5
            return res
        def c10(k):
            r5 = c5(k); r2 = 1 if (k & ~m) == 0 else 0
            for r in range(10):
                if r % 5 == r5 and r % 2 == r2: return r
        s0 = sum(int(ch) * c10(j) for j, ch in enumerate(s)) % 10
        s1 = sum(int(ch) * c10(j - 1) for j, ch in enumerate(s) if j) % 10
        return s0 == s1

