class Solution {
public:
    bool hasSameDigits(string s) {
        int n = s.size(), m = n - 2;
        int d5[8], dn = 0;
        for (int x = m; x > 0; x /= 5) d5[dn++] = x % 5;
        static const int C5[5][5] = {{0},{0,1},{0,2,1},{0,3,3,1},{0,4,1,4}};
        auto c5 = [&](int k) {
            int res = 1, cur = 1;
            for (int i = 0; i < dn; i++) {
                int r = (k / cur) % 5; cur *= 5;
                if (r > d5[i]) return 0;
                res = res * C5[d5[i]][r] % 5;
            }
            return res;
        };
        auto c10 = [&](int k) {
            int r5 = c5(k), r2 = ((k & ~m) == 0) ? 1 : 0;
            for (int r = 0; r < 10; r++)
                if (r % 5 == r5 && r % 2 == r2) return r;
            return 0;
        };
        long long s0 = 0, s1 = 0;
        for (int j = 0; j < n; j++) {
            int d = s[j] - '0';
            s0 += (long long)d * c10(j);
            if (j) s1 += (long long)d * c10(j - 1);
        }
        return s0 % 10 == s1 % 10;
    }
};

