var hasSameDigits = function(s) {
    const n = s.length, m = n - 2;
    const d5 = [];
    for (let x = m; x > 0; x = Math.floor(x / 5)) d5.push(x % 5);
    const C5 = [[0],[0,1],[0,2,1],[0,3,3,1],[0,4,1,4]];
    const c5 = k => {
        let res = 1, cur = 1;
        for (const p of d5) {
            const r = Math.floor(k / cur) % 5; cur *= 5;
            if (r > p) return 0;
            res = res * C5[p][r] % 5;
        }
        return res;
    };
    const c10 = k => {
        const r5 = c5(k), r2 = ((k & ~m) === 0) ? 1 : 0;
        for (let r = 0; r < 10; r++)
            if (r % 5 === r5 && r % 2 === r2) return r;
        return 0;
    };
    let s0 = 0, s1 = 0;
    for (let j = 0; j < n; j++) {
        const d = +s[j];
        s0 += d * c10(j);
        if (j) s1 += d * c10(j - 1);
    }
    return s0 % 10 === s1 % 10;
};
